const maskCanvas=document.createElement('canvas'),maskContext=maskCanvas.getContext('2d'),paint=$('paint-canvas'),paintContext=paint.getContext('2d');
let painting=false,erasing=false,previousPoint=null;
function showPage(id){if(!pages[id])return;current=id;for(const key in pages)$('page-'+key).hidden=key!==id;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));$('page-title').textContent=pages[id][0];$('page-description').textContent=pages[id][1];if(id==='library')loadLibrary();if(id==='editor')requestAnimationFrame(fitCanvas)}
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,8000)}
async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Wan-Token':token,...(data===undefined?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:JSON.stringify(data)})});const result=await response.json();if(!response.ok)throw Error(result.error||'Operation failed.');return result}
async function action(path,data={}){try{return await api(path,data)}catch(e){notify(e.message);throw e}}
function mediaURL(item){return `/${item.media_type==='video'?'video':'image'}/${encodeURIComponent(item.id)}?token=${encodeURIComponent(token)}`}
function thumbURL(item){return `/thumbnail/${encodeURIComponent(item.id)}?token=${encodeURIComponent(token)}`}
function pack(id){return id==='wan13'?state?.base_model:state?.packs.find(p=>p.id===id)}
function referenceLimit(){return (pack($('emodel').value)?.max_references||3)-1;}
function updateAvailability(){for(const p of ['i','e','v']){const key=$(p+'model').value,ready=key==='wan13'?state?.ready:pack(key)?.ready;$(p+'-ready').textContent=ready?'Model installed':'Install this model in Models';}const native=['zimage','fluxklein','flux3'].includes($('imodel').value);$('icfg').disabled=native;$('inegative').disabled=native;const sdxl=['juggernaut','dreamshaper','illustrious'].includes($('emodel').value);$('strength-panel').hidden=!sdxl;$('reference-panel').hidden=sdxl;$('ecfg').disabled=$('enegative').disabled=['fluxklein','flux3'].includes($('emodel').value);$('edit-hint').textContent=sdxl?'Describe the full desired image. Redraw strength controls how much changes.':$('emodel').value==='flux3'?'Describe the complete edited result. Starting image: <ref_image_0>; extra references: <ref_image_1> through <ref_image_9>.':'Describe the change. Refer to the starting image as image 1.';}
function applyModel(p){const defaults=pack($(p+'model').value)?.defaults||{steps:8,cfg:2};$(p+'steps').value=defaults.steps;$(p+'cfg').value=defaults.cfg;updateAvailability();if(p==='e'){if(['juggernaut','dreamshaper','illustrious'].includes($('emodel').value))references=[];else if(references.length>referenceLimit()){references=references.slice(0,referenceLimit());notify('Reference list limited to '+referenceLimit()+' extras for this model.');}}renderSources();renderLoraSummaries()}
function values(p){return {...Object.fromEntries(['model','prompt','negative','width','height','steps','cfg','seed','memory'].map(k=>[k,$(p+k).value])),loras:savedLoras($(p+'model').value)}}
function fill(p,options){if(!options)return;for(const key in options){const el=$(p+key);if(el&&typeof options[key]!=='object')el.value=options[key]}}
function showResult(item,target){if(!item)return;const video=target==='video';$(target+'-preview').innerHTML=video?`<video controls preload="metadata" src="${mediaURL({...item,media_type:'video'})}"></video>`:`<img src="${mediaURL(item)}" alt="Generated image">`;renderActions(item,target+'-actions',video)}
function renderActions(item,id,video=false){const parent=$(id);parent.hidden=false;parent.innerHTML=`<span class="meta">${esc(item.width?`${item.width} × ${item.height}`:item.name)}${item.options?.seed!==undefined?' · seed '+esc(item.options.seed):''}</span>${video?'<button data-result="frame">Use a frame…</button>':'<button data-result="edit">Send to editor</button><button data-result="animate">Send to video</button>'}<a download="${esc(item.name)}" href="${mediaURL({...item,media_type:video?'video':'image'})}">Save a copy</a>`;parent.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>b.dataset.result==='frame'?openMedia({...item,media_type:'video'}):sendImage(item,b.dataset.result==='edit'?'editor':'video'))}
function renderSources(){for(const [p,item] of [['e',editorSource],['v',videoSource]]){$(p+'source').innerHTML=item?`<div class="source-chip"><img src="${mediaURL(item)}" alt=""><span>${esc(item.name)}<small>${item.width} × ${item.height}</small></span><button type="button" data-pick="${p}">Change</button></div>`:'No image selected.'} $('reference-chips').innerHTML=references.map((item,i)=>`<div class="source-chip"><img src="${mediaURL(item)}" alt=""><span>${$('emodel').value==='flux3'?esc('<ref_image_'+(i+1)+'>'):'Image '+(i+2)} · ${esc(item.name)}</span><button type="button" data-remove-ref="${i}" aria-label="Remove reference">×</button></div>`).join('');$('add-reference').disabled=references.length>=referenceLimit();document.querySelector('[data-import=reference]').disabled=references.length>=referenceLimit()||state?.busy;}
