async function poll(){try{const next=await api('/api/state');state=next;failures=0;if(!initialized)initialize();$('stage').textContent=next.stage;$('error').textContent=next.error||'';$('progress').classList.toggle('indeterminate',next.busy&&next.progress===null);$('progress').style.width=next.progress===null?'35%':Math.round((next.progress||0)*100)+'%';$('cancel').hidden=!next.busy;document.querySelectorAll('[data-job]').forEach(b=>b.disabled=next.busy);$('release').disabled=next.busy;document.querySelectorAll('[data-import]').forEach(b=>b.disabled=next.busy||(b.dataset.import==='reference'&&references.length>=referenceLimit()));renderResources();renderPacks();renderLoras();updateAvailability();if(typeof renderTools==='function')renderTools();$('activity').textContent=(next.log||[]).join('\n');if(next.result&&next.result.id!==lastVideo){lastVideo=next.result.id;showResult(next.result,'video')}const latest=next.latest_media;if(latest&&latest.id!==lastImage){lastImage=latest.id;showResult(latest,latest.media_type==='video'?'video':'image');if(latest.kind==='edited'||latest.kind==='crop'){ $('edit-result-img').src=mediaURL(latest);$('edit-result-slot').hidden=false;$('editor-stage').classList.add('has-result');renderActions(latest,'edit-actions');requestAnimationFrame(fitCanvas)}}if(pending&&!next.busy){if(next.error){pending=null}else if(latest&&latest.id!==pending.before){const target=pending.target;pending=null;if(target==='library')showPage('library');else sendImage(latest,target)}}if(next.library_revision!==lastRevision){lastRevision=next.library_revision;if(current==='library')loadLibrary()}}catch(e){failures++;if(failures>=3){$('stage').textContent='Connection interrupted. Reconnecting…';$('error').textContent=e.message}}finally{setTimeout(poll,state?.busy?1500:2500)}}
