$('edit-form').onsubmit=async e=>{e.preventDefault();if(!editorSource){notify('Choose a starting image first.');return}if($('etool').value==='crop'){const o={id:editorSource.id};for(const [key,id] of [['x','crop-x'],['y','crop-y'],['crop_width','crop-w'],['crop_height','crop-h'],['width','resize-w'],['height','resize-h']])o[key]=$(id).value;await action('/api/images/crop',o).catch(()=>{});return}if(!$('eprompt').value.trim()){notify('Describe the edit first.');return}const o={...values('e'),source_image:editorSource.id,references:references.map(x=>x.id),strength:$('estrength').value};if($('etool').value==='mask')o.mask=maskCanvas.toDataURL('image/png');await action('/api/images/edit',o).catch(()=>{})};
$('video-form').onsubmit=async e=>{e.preventDefault();const o={...values('v'),mode:$('vmode').value,source_image:videoSource?.id||'',frames:$('vframes').value==='custom'?$('vframecount').value:$('vframes').value,fps:$('vfps').value,shift:$('vshift').value,sampler:$('vsampler').value,scheduler:$('vscheduler').value,audio:$('vaudio').checked,loras:savedLoras($('vmodel').value)};await action('/api/generate',o).catch(()=>{})};
$('imodel').onchange=()=>applyModel('i');$('emodel').onchange=()=>applyModel('e');$('etool').onchange=editorToolChanged;$('vmodel').onchange=()=>videoModelChanged();$('vmode').onchange=()=>$('video-source-controls').hidden=$('vmode').value!=='image';
for(const p of ['i','v'])$(p+'shape').onchange=()=>{const value=$(p+'shape').value;$(p+'-size').hidden=value!=='custom';if(value!=='custom')[$(p+'width').value,$(p+'height').value]=value.split('x')};
$('vframes').onchange=()=>{$('v-custom-frames').hidden=$('vframes').value!=='custom';updateDuration()};$('vframecount').oninput=$('vfps').oninput=updateDuration;
for(const id of ['ewidth','eheight'])$(id).onchange=()=>{resetMask();fitCanvas()};
$('add-reference').onclick=()=>openPicker('reference');$('crop-reset').onclick=resetCrop;$('crop-square').onclick=()=>{if(!editorSource)return;const size=Math.min(editorSource.width,editorSource.height);$('crop-x').value=Math.floor((editorSource.width-size)/2);$('crop-y').value=Math.floor((editorSource.height-size)/2);$('crop-w').value=$('crop-h').value=size;$('resize-w').value=$('resize-h').value=Math.min(size,4096);updateCropRect()};
for(const id of ['crop-x','crop-y','crop-w','crop-h'])$(id).oninput=()=>{updateCropRect();if($('keep-aspect').checked)$('resize-h').value=Math.round(Number($('resize-w').value)*Number($('crop-h').value)/Number($('crop-w').value))};
$('resize-w').oninput=()=>{if($('keep-aspect').checked)$('resize-h').value=Math.round(Number($('resize-w').value)*Number($('crop-h').value)/Number($('crop-w').value))};$('resize-h').oninput=()=>{if($('keep-aspect').checked)$('resize-w').value=Math.round(Number($('resize-h').value)*Number($('crop-w').value)/Number($('crop-h').value))};
$('import-file').onchange=e=>{importFile(e.target.files[0],importTarget);e.target.value=''};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)showPage(b.dataset.page);if(b.dataset.loraFor)openLoras($(b.dataset.loraFor+'model').value);if(b.dataset.help){const [title,copy]=help[b.dataset.help];$('help-title').textContent=title;$('help-copy').textContent=copy;$('help-dialog').showModal()}if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.pick)openPicker(b.dataset.pick);if(b.dataset.import){importTarget=b.dataset.import;$('import-file').click()}if(b.dataset.removeRef!==undefined){references.splice(Number(b.dataset.removeRef),1);renderSources()}});
$('select-image-packs').onclick=()=>{document.querySelectorAll('.pack-check:not(:disabled)').forEach(e=>e.checked=['image','editor'].includes(pack(e.value)?.kind));downloadEstimate()};$('install-selected').onclick=async()=>{const keys=[...document.querySelectorAll('.pack-check:checked')].map(x=>x.value);if(!keys.length){notify('Select at least one model.');return}await action('/api/packs/install',{packs:keys,token:$('access-token').value}).catch(()=>{});$('access-token').value=''};
$('install-runtime').onclick=async()=>{await action('/api/install',{token:$('access-token').value}).catch(()=>{});$('access-token').value=''};$('cancel').onclick=()=>action('/api/cancel').catch(()=>{});$('release').onclick=()=>action('/api/release').catch(()=>{});$('log-toggle').onclick=()=>$('log-dialog').showModal();
$('save-settings').onclick=()=>action('/api/settings',{output:$('output').value}).then(()=>notify('Output folder saved.')).catch(()=>{});$('pick-output').onclick=()=>api('/api/pick-folder',{}).then(x=>{if(x.path)$('output').value=x.path}).catch(e=>notify(e.message));
for(const kind of ['videos','images','logs','loras'])$('open-'+kind).onclick=()=>{if(kind==='videos'&&window.chrome?.webview)window.chrome.webview.postMessage('open-videos');else action('/api/open-folder',{kind,...(kind==='loras'?{model:$('lora-target').value}:{})}).catch(()=>{})};
$('import-loras').onclick=()=>{if(window.chrome?.webview)window.chrome.webview.postMessage('import-loras:'+$('lora-target').value);else notify('Local LoRA imports are available in the desktop app. You can also paste a Hugging Face file link.');};
$('download-lora').onclick=async()=>{await action('/api/loras/download',{url:$('lora-url').value,token:$('lora-token').value,model:$('lora-target').value}).catch(()=>{});$('lora-token').value=''};$('save-loras').onclick=async()=>{const model=$('lora-target').value;try{await action('/api/loras/select',{model,loras:selectedLoras()});delete loraDrafts[model];state=await api('/api/state');renderLoras(true);notify('LoRA selection saved for '+loraInfo(model).name+'.')}catch{}};
function fullscreen(){if(window.chrome?.webview)window.chrome.webview.postMessage('toggle-fullscreen');else if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else document.documentElement.requestFullscreen().catch(()=>notify('Maximize the window to use more space.'))}$('fullscreen').onclick=fullscreen;document.addEventListener('keydown',e=>{if(e.key==='F11'){e.preventDefault();fullscreen()}else if(e.key==='Escape'&&window.chrome?.webview){window.chrome.webview.postMessage('exit-fullscreen')}});new ResizeObserver(()=>requestAnimationFrame(fitCanvas)).observe($('canvas-space'));
for(const id of ['page-editor','page-video','page-images']){const area=$(id);area.ondragover=e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();area.classList.add('drop-active')}};area.ondragleave=e=>{if(!area.contains(e.relatedTarget))area.classList.remove('drop-active')};area.ondrop=e=>{e.preventDefault();area.classList.remove('drop-active');importFile(e.dataTransfer.files[0],id==='page-video'?'video':'editor')}}
window.addEventListener('unhandledrejection',e=>{e.preventDefault();notify(e.reason?.message||String(e.reason))});showPage('images');poll();
